WEINGUT = {
    'Bodegas Muga': {'text': 'Bodegas Muga ist ein spanisches Weingut in Haro, in der Rioja Alta. Isaac Muga Martínez und seine Frau Aurora Caño gründeten es 1932; heute entstehen dort Rot-, Rosé- und Weissweine aus Tempranillo, Garnacha, Mazuelo, Malvasía und Viura.', 'quelle': E + 'Bodegas_Muga'},
    'Bodegas Vega Sicilia': {'text': 'Vega Sicilia ist ein spanisches Weingut im Norden der Iberischen Halbinsel. Seine Weinberge liegen in der Ribera del Duero. Die Eigentümerfamilie Álvarez ist Mitglied der Vereinigung Primum Familiae Vini.', 'quelle': W + 'Vega_Sicilia'},
    'Bruno Giacosa': {'text': 'Bruno Giacosa († 21. Januar 2018) war ein Winzer aus Neive in den Langhe im Piemont. Er machte Barbaresco und Barolo, dazu Arneis, Barbera, Dolcetto und einen Schaumwein. Weine aus eigenen Weinbergen tragen den Namen Azienda Agricola Falletto. Beim Nebbiolo galt er als Traditionalist, man nannte ihn das «Genie von Neive».', 'quelle': E + 'Bruno_Giacosa'},
    'Champagne Agrapart et fils': {'text': 'Agrapart ist ein Winzer-Champagnerhaus, das biologisch und nach Lage arbeitet. Arthur Agrapart gründete es 1894 in Avize; sein Enkel Pierre baute es in den 1950er- und 1960er-Jahren aus. Seit 1984 führt Pascal Agrapart das Haus, seit 2018 mit seinem Sohn Ambroise in der fünften Generation.', 'quelle': E + 'Pascal_Agrapart'},
    'Champagne Bollinger': {'text': 'Champagne Bollinger ist ein Champagnerhaus in Aÿ, gegründet 1829 und seither von Mitgliedern der Familie Bollinger geführt. Zu seinen Weinen gehören Vieilles Vignes Françaises, Grande Année, R.D. und die Special Cuvée.', 'quelle': W + 'Champagne_Bollinger'},
    'Champagne Delamotte': {'text': 'Champagne Delamotte ist ein kleines Champagnerhaus. Zusammen mit seinem Schwesterhaus Salon ist es das historische Haus der Gruppe Laurent-Perrier.', 'quelle': E + 'Champagne_Delamotte'},
    'Champagne Dom Pérignon': {'text': 'Dom Pérignon ist eine Champagnermarke von Moët & Chandon, benannt nach dem Mönch Dom Pérignon. Er entsteht als Cuvée aus Chardonnay und Pinot Noir und nur in guten Jahren als Jahrgang, als Weisswein und seltener als Rosé.', 'quelle': W + 'Dom_P%C3%A9rignon_(Champagner)'},
    'Champagne Gosset': {'text': 'Gosset, gegründet 1584, ist das älteste Weinhaus der Champagne. Pierre Gosset, Ratsherr und Winzer in Aÿ, machte damals stille, meist rote Weine aus eigenen Trauben. Als der Wein um Aÿ im 18. Jahrhundert zu perlen begann, wandte sich die Familie dem Champagner zu.', 'quelle': E + 'Gosset'},
    'Champagne Laurent-Perrier': {'text': 'Laurent-Perrier ist ein Champagnerhaus, gegründet 1812, und das Stammhaus der Gruppe Laurent-Perrier, zu der auch Salon, De Castellane und Delamotte gehören. Über 1200 Traubenbauern liefern unter Vertrag; das Haus verkauft in mehr als 120 Länder.', 'quelle': E + 'Laurent-Perrier'},
    'Champagne Louis Roederer': {'text': 'Champagne Louis Roederer ist ein Champagnerhaus aus Reims, gegründet 1776 und seit 1819 in Familienbesitz, eines der letzten unabhängigen Häuser. Es macht jährlich 3,5 Millionen Flaschen, darunter den Cristal, und verkauft in 80 Länder.', 'quelle': W + 'Champagne_Louis_Roederer'},
    'Champagne Ruinart': {'text': 'Ruinart ist ein Champagnerhaus in Reims, gegründet am 1. September 1729 von Nicolas Irénée Ruinart, dem Neffen des Benediktinermönchs Dom Thierry Ruinart. Es ist das älteste noch tätige Champagnerhaus.', 'quelle': W + 'Ruinart'},
    'Champagne Taittinger': {'text': 'Taittinger ist ein Champagnerhaus in Reims. Es entstand 1931 aus der Kellerei Forest & Fourneaux, die seit 1734 bestand, und gehört bis heute der Familie. Seit 2020 ist Vitalie Taittinger Präsidentin des Hauses.', 'quelle': W + 'Taittinger'},
    'Château Lafaurie-Peyraguey': {'text': 'Château Lafaurie-Peyraguey ist eines der bekanntesten Süssweingüter von Sauternes, gleich neben Château d’Yquem in Bommes, im Rang eines Premier Cru. Die 37 Hektar sind fast ganz mit Sémillon bepflanzt, dazu Sauvignon Blanc und Muscadelle; die Reben sind im Schnitt 40 Jahre alt. Gelesen wird von Hand in vier bis sieben Durchgängen, um die edelfaulen Beeren einzeln auszuwählen.', 'quelle': W + 'Ch%C3%A2teau_Lafaurie-Peyraguey'},
    'Château de Rayne Vigneau': {'text': 'Château de Rayne-Vigneau liegt in Bommes in der Appellation Sauternes im Bordelais und wurde 1855 als Premier Cru Classé eingestuft. Das Gut hat 80 Hektar, die ganz dem Weinbau dienen.', 'quelle': W + 'Ch%C3%A2teau_de_Rayne-Vigneau'},
    'Domaine de Villaine': {'text': 'Aubert de Villaine (geboren 1939 in Rennes) ist Winzer und Mitinhaber der Domaine de la Romanée-Conti im Burgund.', 'quelle': W + 'Aubert_de_Villaine'},
    'Domaine de la Romanée-Conti': {'text': 'Die Domaine de la Romanée-Conti gilt als berühmtestes Weingut des Burgund. Sie liegt in Vosne-Romanée an der Côte d’Or; ihr Name kommt von der Grand-Cru-Lage Romanée-Conti, die ihr allein gehört.', 'quelle': W + 'Domaine_de_la_Roman%C3%A9e-Conti'},
    'Dominio de Pingus': {'text': 'Dominio de Pingus liegt in Quintanilla de Onésimo bei Valladolid, mit Weinbergen in La Horra in der Ribera del Duero. Der Hauptwein Pingus gilt als Kultwein; daneben entstehen Flor de Pingus und die Cuvée Amelia.', 'quelle': E + 'Dominio_de_Pingus'},
    'M. Chapoutier': {'text': 'Maison M. Chapoutier ist ein Weingut und Handelshaus in Tain-l’Hermitage an der Rhône, mit Weinen aus der ganzen Region; am bekanntesten sind seine roten und weissen Hermitage. Seit 1996 tragen alle Etiketten auch Blindenschrift.', 'quelle': E + 'Chapoutier'},
    'Miguel Torres': {'text': 'Miguel Torres ist ein Wein- und Brandyhaus mit Sitz in Barcelona, 1870 von Jaime Torres Vendrell gegründet. Den Namen trägt es nach Miguel Torres Carbó; heute führt es sein Sohn Miguel Agustín Torres Riera.', 'quelle': W + 'Miguel_Torres_(Weingut)'},
    'R. López de Heredia – Viña Tondonia': {'text': 'López de Heredia ist ein Weingut in der Rioja, gegründet 1877, mit rund 170 Hektar Weinbergen. Es gilt als eines der traditionellsten der Rioja: grosse Fässer aus amerikanischer Eiche und Weine, auch weisse, die oft jahrzehntelang reifen, bevor sie verkauft werden.', 'quelle': E + 'Bodegas_L%C3%B3pez_de_Heredia'},
    'Tenuta San Guido': {'text': 'Tenuta San Guido liegt in Bolgheri in der Toskana und ist bekannt für Supertoskaner. Hier entsteht der Sassicaia im Stil eines Bordeaux, dazu Guidalberto und Le Difese. Das Gut gehört zur Vereinigung Primum Familiae Vini.', 'quelle': E + 'Tenuta_San_Guido'},
    'Tenuta Tignanello': {'text': 'Der Tignanello ist ein Rotwein aus der Toskana, Anfang der 1970er-Jahre unter Marchese Piero Antinori und seinem Önologen Giacomo Tachis entstanden. Er gilt als Wegbereiter der Supertoskaner; der erste Jahrgang war 1971.', 'quelle': W + 'Tignanello'},
    'Weingut A. Christmann': {'text': 'Das Weingut Christmann liegt in Gimmeldingen bei Neustadt an der Weinstrasse. Auf 19 Hektar wachsen vor allem Riesling und Spätburgunder. Seit 2018 führen Steffen Christmann und seine Tochter Sophie den Betrieb; er ist Mitglied im VDP und bei Respekt Biodyn.', 'quelle': W + 'Weingut_Christmann'},
    'Weingut Battenfeld-Spanier': {'text': 'Battenfeld-Spanier liegt in Hohen-Sülzen im Wonnegau, Rheinhessen. Hans-Oliver Spanier gründete den Betrieb 1991; seit 2008 ist er im VDP. Er bewirtschaftet rund 50 Hektar, vor allem mit Riesling.', 'quelle': W + 'Weingut_Battenfeld-Spanier'},
    'Weingut Bernhard Huber': {'text': 'Das Weingut Bernhard Huber liegt in Malterdingen im badischen Breisgau. Auf 26 Hektar wächst vor allem Spätburgunder. Seit 1995 ist es Mitglied im VDP.', 'quelle': W + 'Weingut_Bernhard_Huber'},
    'Weingut Dr. Bürklin-Wolf': {'text': 'Dr. Bürklin-Wolf in Wachenheim an der Weinstrasse ist einer der grössten Weinbaubetriebe der Pfalz und der grösste, der selbst vermarktet. Das Weingut ist Mitglied im VDP.', 'quelle': W + 'Weingut_Dr._B%C3%BCrklin-Wolf'},
    'Weingut Emmerich Knoll': {'text': 'Das Weingut Emmerich Knoll liegt in Unterloiben bei Dürnstein in der Wachau, Niederösterreich.', 'quelle': W + 'Weingut_Emmerich_Knoll'},
    'Weingut Franz Hirtzberger': {'text': 'Das Weingut Franz Hirtzberger liegt in Spitz in der Wachau, Niederösterreich.', 'quelle': W + 'Weingut_Franz_Hirtzberger'},
    'Weingut Joh. Jos. Prüm': {'text': 'Joh. Jos. Prüm ist ein Familienweingut in Wehlen an der Mosel. Johann Josef Prüm gründete es 1911 mit Weinbergen aus seinem Erbe; heute führen es Manfred und Katharina Prüm.', 'quelle': W + 'Weingut_Joh._Jos._Pr%C3%BCm'},
    'Weingut Robert Weil': {'text': 'Das Weingut Robert Weil liegt in Kiedrich im Rheingau. Es ist seit 1907 im VDP und bewirtschaftet knapp 90 Hektar.', 'quelle': W + 'Weingut_Robert_Weil'},
    'Weingut Rudolf Fürst': {'text': 'Das Weingut Rudolf Fürst liegt in Bürgstadt in Franken. Die Familie Fürst ist seit 1638 als Winzerfamilie belegt.', 'quelle': W + 'Weingut_Rudolf_F%C3%BCrst'},
    'Weingut Tement': {'text': 'Das Weingut Tement liegt in Berghausen bei Ehrenhausen an der Weinstrasse, in der Südsteiermark.', 'quelle': W + 'Weingut_Manfred_Tement'},
    'Weingut Wittmann': {'text': 'Das Weingut Wittmann liegt in Westhofen im Wonnegau, Rheinhessen, und bewirtschaftete 2021 rund 28 Hektar. Es ist Mitglied im VDP.', 'quelle': W + 'Weingut_Wittmann'},
    'Weingut von Winning': {'text': 'Das Weingut von Winning in Deidesheim in der Pfalz hiess bis 2009 Dr. Deinhard. Auf rund 80 Hektar entstehen vor allem Rieslinge; es ist Mitglied im VDP.', 'quelle': W + 'Weingut_von_Winning'},
}
